// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./ISniperStrategy.sol";

/**
 * @title PredictFiSniperVaultV3
 * @notice ERC4626 vault with 1% withdrawal tax, per-wallet caps, and configurable limits
 * @dev V3 adds withdrawal tax on top of V2 functionality
 */
contract PredictFiSniperVaultV3 is ERC4626, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice The trading strategy contract
    ISniperStrategy public strategy;

    /// @notice Address that receives performance fees
    address public feeCollector;

    /// @notice Address that receives withdrawal tax
    address public taxCollector;

    /// @notice Performance fee in basis points (e.g., 500 = 5%)
    uint256 public performanceFeeBps;

    /// @notice Withdrawal tax in basis points (e.g., 100 = 1%)
    uint256 public withdrawalTaxBps;

    /// @notice Buffer percentage in basis points to keep as idle USDC
    uint256 public bufferBps;

    /// @notice Last recorded total assets for performance fee calculation
    uint256 public lastTotalAssets;

    /// @notice Maximum total deposits allowed in the vault
    uint256 public maxTotalDeposits;

    /// @notice Maximum assets (USDC) each wallet can deposit
    uint256 public walletDepositCap;

    /// @notice Tracks total deposited per address
    mapping(address => uint256) public walletDeposited;

    /// @notice Emitted when there's not enough liquidity for a withdrawal
    event LiquidityShortfall(uint256 assetsNeeded, uint256 availableAssets);

    /// @notice Emitted when strategy is updated
    event StrategyUpdated(address indexed oldStrategy, address indexed newStrategy);

    /// @notice Emitted when fee collector is updated
    event FeeCollectorUpdated(address indexed oldCollector, address indexed newCollector);

    /// @notice Emitted when tax collector is updated
    event TaxCollectorUpdated(address indexed oldCollector, address indexed newCollector);

    /// @notice Emitted when performance fee is updated
    event PerformanceFeeBpsUpdated(uint256 oldFee, uint256 newFee);

    /// @notice Emitted when withdrawal tax is updated
    event WithdrawalTaxBpsUpdated(uint256 oldTax, uint256 newTax);

    /// @notice Emitted when buffer is updated
    event BufferBpsUpdated(uint256 oldBuffer, uint256 newBuffer);

    /// @notice Emitted when max deposits is updated
    event MaxTotalDepositsUpdated(uint256 oldMax, uint256 newMax);

    /// @notice Emitted when wallet deposit cap is updated
    event WalletDepositCapUpdated(uint256 oldCap, uint256 newCap);

    /// @notice Emitted when idle funds are invested
    event IdleInvested(uint256 amount);

    /// @notice Emitted when performance fees are harvested
    event FeesHarvested(uint256 profit, uint256 feeShares);

    /// @notice Emitted when withdrawal tax is collected
    event WithdrawalTaxCollected(address indexed user, uint256 grossAssets, uint256 taxAmount);

    /**
     * @notice Constructor
     * @param _asset The underlying asset (USDC)
     * @param _strategy The initial trading strategy
     * @param _feeCollector Address to receive performance fees
     * @param _taxCollector Address to receive withdrawal tax
     * @param _performanceFeeBps Performance fee in basis points
     * @param _withdrawalTaxBps Withdrawal tax in basis points
     * @param _bufferBps Buffer percentage in basis points
     * @param _maxTotalDeposits Maximum total deposits allowed
     * @param _walletDepositCap Maximum deposit per wallet
     */
    constructor(
        IERC20 _asset,
        ISniperStrategy _strategy,
        address _feeCollector,
        address _taxCollector,
        uint256 _performanceFeeBps,
        uint256 _withdrawalTaxBps,
        uint256 _bufferBps,
        uint256 _maxTotalDeposits,
        uint256 _walletDepositCap
    )
        ERC4626(_asset)
        ERC20("PredictFi Sniper Vault V3", "pSNIPERv3")
        Ownable(msg.sender)
    {
        require(address(_strategy) != address(0), "Invalid strategy");
        require(_feeCollector != address(0), "Invalid fee collector");
        require(_taxCollector != address(0), "Invalid tax collector");
        require(_performanceFeeBps <= 5000, "Fee too high"); // Max 50%
        require(_withdrawalTaxBps <= 1000, "Tax too high"); // Max 10%
        require(_bufferBps <= 10000, "Buffer too high");

        strategy = _strategy;
        feeCollector = _feeCollector;
        taxCollector = _taxCollector;
        performanceFeeBps = _performanceFeeBps;
        withdrawalTaxBps = _withdrawalTaxBps;
        bufferBps = _bufferBps;
        maxTotalDeposits = _maxTotalDeposits;
        walletDepositCap = _walletDepositCap;
        lastTotalAssets = 0;
    }

    // ============================================
    // View Functions
    // ============================================

    /**
     * @notice Returns total assets under management
     * @return Total idle USDC plus strategy value
     */
    function totalAssets() public view override returns (uint256) {
        uint256 idle = IERC20(asset()).balanceOf(address(this));
        uint256 strategyValue = address(strategy) != address(0)
            ? strategy.totalStrategyValue()
            : 0;
        return idle + strategyValue;
    }

    /**
     * @notice Calculate gross assets needed to deliver net assets after tax
     * @param netAssets The net amount user wants to receive
     * @return Gross assets before tax (what user needs to burn shares for)
     */
    function grossAssetsForNet(uint256 netAssets) public view returns (uint256) {
        // net = gross * (1 - tax/10000)
        // gross = net / (1 - tax/10000) = net * 10000 / (10000 - tax)
        return (netAssets * 10000) / (10000 - withdrawalTaxBps);
    }

    /**
     * @notice Preview how many shares needed to withdraw assets (ERC4626 compliant)
     * @dev Returns shares needed to receive exactly 'assets' after tax
     * @param assets The net amount user will receive
     * @return Shares to burn
     */
    function previewWithdraw(uint256 assets) public view override returns (uint256) {
        // Calculate gross amount needed (before tax) to deliver 'assets' net
        uint256 grossAssets = grossAssetsForNet(assets);
        // Convert gross to shares
        return _convertToShares(grossAssets, Math.Rounding.Ceil);
    }

    /**
     * @notice Preview assets received after redeeming shares (ERC4626 compliant)
     * @dev Returns net assets after 1% tax deduction
     * @param shares The shares to redeem
     * @return Net assets user will receive
     */
    function previewRedeem(uint256 shares) public view override returns (uint256) {
        uint256 grossAssets = _convertToAssets(shares, Math.Rounding.Floor);
        uint256 tax = (grossAssets * withdrawalTaxBps) / 10000;
        return grossAssets - tax;
    }

    // ============================================
    // Owner Functions
    // ============================================

    /**
     * @notice Update the trading strategy
     * @param _strategy New strategy address
     */
    function setStrategy(ISniperStrategy _strategy) external onlyOwner {
        require(address(_strategy) != address(0), "Invalid strategy");
        emit StrategyUpdated(address(strategy), address(_strategy));
        strategy = _strategy;
    }

    /**
     * @notice Update the fee collector address
     * @param _feeCollector New fee collector address
     */
    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "Invalid fee collector");
        emit FeeCollectorUpdated(feeCollector, _feeCollector);
        feeCollector = _feeCollector;
    }

    /**
     * @notice Update the tax collector address
     * @param _taxCollector New tax collector address
     */
    function setTaxCollector(address _taxCollector) external onlyOwner {
        require(_taxCollector != address(0), "Invalid tax collector");
        emit TaxCollectorUpdated(taxCollector, _taxCollector);
        taxCollector = _taxCollector;
    }

    /**
     * @notice Update the performance fee
     * @param _performanceFeeBps New fee in basis points
     */
    function setPerformanceFeeBps(uint256 _performanceFeeBps) external onlyOwner {
        require(_performanceFeeBps <= 5000, "Fee too high");
        emit PerformanceFeeBpsUpdated(performanceFeeBps, _performanceFeeBps);
        performanceFeeBps = _performanceFeeBps;
    }

    /**
     * @notice Update the withdrawal tax
     * @param _withdrawalTaxBps New tax in basis points
     */
    function setWithdrawalTaxBps(uint256 _withdrawalTaxBps) external onlyOwner {
        require(_withdrawalTaxBps <= 1000, "Tax too high");
        emit WithdrawalTaxBpsUpdated(withdrawalTaxBps, _withdrawalTaxBps);
        withdrawalTaxBps = _withdrawalTaxBps;
    }

    /**
     * @notice Update the buffer percentage
     * @param _bufferBps New buffer in basis points
     */
    function setBufferBps(uint256 _bufferBps) external onlyOwner {
        require(_bufferBps <= 10000, "Buffer too high");
        emit BufferBpsUpdated(bufferBps, _bufferBps);
        bufferBps = _bufferBps;
    }

    /**
     * @notice Update the maximum total deposits
     * @param _maxTotalDeposits New maximum deposits
     */
    function setMaxTotalDeposits(uint256 _maxTotalDeposits) external onlyOwner {
        emit MaxTotalDepositsUpdated(maxTotalDeposits, _maxTotalDeposits);
        maxTotalDeposits = _maxTotalDeposits;
    }

    /**
     * @notice Update the per-wallet deposit cap
     * @param _cap New wallet deposit cap
     */
    function setWalletDepositCap(uint256 _cap) external onlyOwner {
        emit WalletDepositCapUpdated(walletDepositCap, _cap);
        walletDepositCap = _cap;
    }

    // ============================================
    // Core Functions
    // ============================================

    /**
     * @notice Invest idle USDC above the buffer target into the strategy
     */
    function investIdle() external nonReentrant {
        uint256 total = totalAssets();
        uint256 targetIdle = (total * bufferBps) / 10000;
        uint256 currentIdle = IERC20(asset()).balanceOf(address(this));

        if (currentIdle > targetIdle) {
            uint256 toInvest = currentIdle - targetIdle;
            IERC20(asset()).safeIncreaseAllowance(address(strategy), toInvest);
            strategy.invest(toInvest);
            emit IdleInvested(toInvest);
        }
    }

    /**
     * @notice Harvest performance fees on profits
     * @dev Mints vault shares to feeCollector based on profit since last harvest
     */
    function harvest() external nonReentrant {
        uint256 currentTotal = totalAssets();

        if (currentTotal > lastTotalAssets) {
            uint256 profit = currentTotal - lastTotalAssets;
            uint256 feeAssets = (profit * performanceFeeBps) / 10000;

            if (feeAssets > 0) {
                uint256 feeShares = convertToShares(feeAssets);
                if (feeShares > 0) {
                    _mint(feeCollector, feeShares);
                    emit FeesHarvested(profit, feeShares);
                }
            }
        }

        lastTotalAssets = totalAssets();
    }

    // ============================================
    // Override Deposit/Mint with Per-Wallet Caps
    // ============================================

    /**
     * @notice Deposit assets with global and per-wallet cap enforcement
     */
    function deposit(
        uint256 assets,
        address receiver
    ) public override nonReentrant returns (uint256) {
        require(totalAssets() + assets <= maxTotalDeposits, "cap reached");
        require(walletDeposited[receiver] + assets <= walletDepositCap, "wallet cap reached");

        walletDeposited[receiver] += assets;
        uint256 shares = super.deposit(assets, receiver);
        lastTotalAssets = totalAssets();
        return shares;
    }

    /**
     * @notice Mint shares with global and per-wallet cap enforcement
     */
    function mint(
        uint256 shares,
        address receiver
    ) public override nonReentrant returns (uint256) {
        uint256 assets = previewMint(shares);
        require(totalAssets() + assets <= maxTotalDeposits, "cap reached");
        require(walletDeposited[receiver] + assets <= walletDepositCap, "wallet cap reached");

        walletDeposited[receiver] += assets;
        uint256 result = super.mint(shares, receiver);
        lastTotalAssets = totalAssets();
        return result;
    }

    // ============================================
    // Override Withdraw/Redeem with Tax and Liquidity
    // ============================================

    /**
     * @notice Withdraw assets with 1% tax (ERC4626 compliant)
     * @dev User specifies net assets they want to receive. Tax is calculated on gross.
     * @param assets The NET amount user wants to receive (after tax)
     * @param receiver Address to receive the net assets
     * @param owner Address whose shares will be burned
     * @return shares Amount of shares burned
     */
    function withdraw(
        uint256 assets,
        address receiver,
        address owner
    ) public override nonReentrant returns (uint256) {
        // 'assets' is what user wants to receive (net)
        // Calculate gross amount needed to deliver 'assets' after tax
        uint256 grossAssets = grossAssetsForNet(assets);
        uint256 tax = grossAssets - assets;

        // Prepare liquidity for gross amount
        _prepareLiquidity(grossAssets);

        // Calculate shares to burn (based on gross assets)
        uint256 shares = _convertToShares(grossAssets, Math.Rounding.Ceil);

        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, shares);
        }

        _burn(owner, shares);

        // Transfer tax to collector, net to receiver
        IERC20(asset()).safeTransfer(taxCollector, tax);
        IERC20(asset()).safeTransfer(receiver, assets);

        emit Withdraw(msg.sender, receiver, owner, assets, shares);
        emit WithdrawalTaxCollected(owner, grossAssets, tax);

        lastTotalAssets = totalAssets();
        return shares;
    }

    /**
     * @notice Redeem shares with 1% tax (ERC4626 compliant)
     * @dev User specifies shares to burn. Receives net assets after tax.
     * @param shares Amount of shares to redeem
     * @param receiver Address to receive the net assets
     * @param owner Address whose shares will be burned
     * @return Net assets sent to receiver
     */
    function redeem(
        uint256 shares,
        address receiver,
        address owner
    ) public override nonReentrant returns (uint256) {
        // Calculate gross assets for the shares
        uint256 grossAssets = _convertToAssets(shares, Math.Rounding.Floor);
        uint256 tax = (grossAssets * withdrawalTaxBps) / 10000;
        uint256 netAssets = grossAssets - tax;

        // Prepare liquidity for gross amount
        _prepareLiquidity(grossAssets);

        if (msg.sender != owner) {
            _spendAllowance(owner, msg.sender, shares);
        }

        _burn(owner, shares);

        // Transfer tax to collector, net to receiver
        IERC20(asset()).safeTransfer(taxCollector, tax);
        IERC20(asset()).safeTransfer(receiver, netAssets);

        emit Withdraw(msg.sender, receiver, owner, netAssets, shares);
        emit WithdrawalTaxCollected(owner, grossAssets, tax);

        lastTotalAssets = totalAssets();
        return netAssets;
    }

    // ============================================
    // Internal Functions
    // ============================================

    /**
     * @notice Prepare liquidity for a withdrawal
     * @param assetsNeeded Amount of assets needed for the withdrawal
     * @dev Pulls from strategy if idle balance is insufficient
     */
    function _prepareLiquidity(uint256 assetsNeeded) internal {
        uint256 idle = IERC20(asset()).balanceOf(address(this));

        if (idle < assetsNeeded) {
            uint256 shortfall = assetsNeeded - idle;
            strategy.withdrawToVault(shortfall);

            uint256 newIdle = IERC20(asset()).balanceOf(address(this));
            if (newIdle < assetsNeeded) {
                emit LiquidityShortfall(assetsNeeded, newIdle);
                revert("Insufficient liquidity");
            }
        }
    }
}

contracts/PredictFiSniperVaultV4.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title PredictFiSniperVaultV4
 * @notice pSNIPER vault with signed NAV oracle pattern
 * @dev Users pay gas for deposit/withdraw, oracle signs NAV off-chain
 * 
 * Key features:
 * - Signed NAV: Bot signs NAV off-chain, users include signature in tx
 * - 1% withdrawal tax to deployer
 * - Per-wallet and total deposit caps
 * - No on-chain NAV updates needed (zero oracle gas cost)
 */
contract PredictFiSniperVaultV4 is ERC20, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ============================================
    // Constants
    // ============================================

    /// @notice NAV type hash for EIP-712 style signing
    bytes32 public constant NAV_TYPEHASH = keccak256(
        "NavData(uint256 nav,uint256 timestamp,uint256 deadline,uint256 roundId,address vault)"
    );

    /// @notice Maximum age of a signed NAV (30 seconds)
    uint256 public constant MAX_NAV_AGE = 30;

    /// @notice Maximum NAV change per update (5% = 500 bps)
    uint256 public constant MAX_NAV_CHANGE_BPS = 500;

    /// @notice Withdrawal tax in basis points (1% = 100 bps)
    uint256 public constant WITHDRAWAL_TAX_BPS = 100;

    /// @notice USDC decimals
    uint256 public constant USDC_DECIMALS = 6;

    /// @notice NAV precision (1e18 for 18 decimal precision)
    uint256 public constant NAV_PRECISION = 1e18;

    // ============================================
    // State Variables
    // ============================================

    /// @notice USDC token address
    IERC20 public immutable usdc;

    /// @notice Oracle signer address (can sign NAV updates)
    address public immutable navSigner;

    /// @notice Tax collector address (receives 1% withdrawal tax)
    address public taxCollector;

    /// @notice Last accepted NAV (stored for reference/UI)
    uint256 public lastNav;

    /// @notice Last accepted roundId (monotonically increasing)
    uint256 public lastRoundId;

    /// @notice Last NAV update timestamp
    uint256 public lastNavTimestamp;

    /// @notice Maximum deposit per wallet (in USDC, 6 decimals)
    uint256 public maxDepositPerWallet;

    /// @notice Maximum total deposits (in USDC, 6 decimals)
    uint256 public maxTotalDeposits;

    /// @notice Total USDC deposited (for cap tracking)
    uint256 public totalDeposited;

    /// @notice Deposits per wallet
    mapping(address => uint256) public walletDeposits;

    /// @notice Pause state
    bool public paused;

    // ============================================
    // Structs
    // ============================================

    /// @notice Signed NAV data structure
    struct NavData {
        uint256 nav;        // NAV per pSNIPE in USDC terms, scaled by 1e18
        uint256 timestamp;  // When this NAV was computed
        uint256 deadline;   // Last block timestamp where this is valid
        uint256 roundId;    // Monotonically increasing index
    }

    // ============================================
    // Events
    // ============================================

    event Deposit(address indexed user, uint256 usdcAmount, uint256 sharesReceived, uint256 navUsed);
    event Withdraw(address indexed user, uint256 sharesRedeemed, uint256 usdcReceived, uint256 taxPaid, uint256 navUsed);
    event NavUpdated(uint256 newNav, uint256 roundId, uint256 timestamp);
    event TaxCollectorUpdated(address indexed oldCollector, address indexed newCollector);
    event CapsUpdated(uint256 perWallet, uint256 total);
    event Paused(bool isPaused);
    event EmergencyWithdraw(address indexed to, uint256 amount);

    // ============================================
    // Constructor
    // ============================================

    /**
     * @param _usdc USDC token address
     * @param _navSigner Address that can sign NAV updates (oracle key)
     * @param _taxCollector Address to receive withdrawal taxes
     * @param _initialNav Initial NAV (1e18 = 1 USDC per pSNIPE)
     * @param _maxPerWallet Max deposit per wallet in USDC (6 decimals)
     * @param _maxTotal Max total deposits in USDC (6 decimals)
     */
    constructor(
        address _usdc,
        address _navSigner,
        address _taxCollector,
        uint256 _initialNav,
        uint256 _maxPerWallet,
        uint256 _maxTotal
    ) ERC20("PredictFi Sniper", "pSNIPER") Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC");
        require(_navSigner != address(0), "Invalid signer");
        require(_taxCollector != address(0), "Invalid tax collector");
        require(_initialNav > 0, "Invalid initial NAV");

        usdc = IERC20(_usdc);
        navSigner = _navSigner;
        taxCollector = _taxCollector;
        lastNav = _initialNav;
        lastRoundId = 0;
        lastNavTimestamp = block.timestamp;
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
    }

    // ============================================
    // Modifiers
    // ============================================

    modifier whenNotPaused() {
        require(!paused, "Vault is paused");
        _;
    }

    // ============================================
    // Core Functions
    // ============================================

    /**
     * @notice Deposit USDC and receive pSNIPE shares
     * @param usdcAmount Amount of USDC to deposit (6 decimals)
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     */
    function deposit(
        uint256 usdcAmount,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        require(usdcAmount > 0, "Amount must be > 0");

        // Verify and apply signed NAV
        _verifyAndApplyNav(navData, signature);

        // Check caps
        require(walletDeposits[msg.sender] + usdcAmount <= maxDepositPerWallet, "Exceeds wallet cap");
        require(totalDeposited + usdcAmount <= maxTotalDeposits, "Exceeds total cap");

        // Calculate shares to mint
        // shares = usdcAmount * NAV_PRECISION / nav
        // Since nav is in 1e18 and usdcAmount is in 1e6, we need to scale
        uint256 sharesToMint = (usdcAmount * NAV_PRECISION) / navData.nav;
        require(sharesToMint > 0, "Shares too small");

        // Transfer USDC from user
        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);

        // Update accounting
        walletDeposits[msg.sender] += usdcAmount;
        totalDeposited += usdcAmount;

        // Mint shares
        _mint(msg.sender, sharesToMint);

        emit Deposit(msg.sender, usdcAmount, sharesToMint, navData.nav);
    }

    /**
     * @notice Redeem pSNIPE shares for USDC (1% tax applies)
     * @param shareAmount Amount of pSNIPE shares to redeem
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     */
    function redeem(
        uint256 shareAmount,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        require(shareAmount > 0, "Amount must be > 0");
        require(balanceOf(msg.sender) >= shareAmount, "Insufficient shares");

        // Verify and apply signed NAV
        _verifyAndApplyNav(navData, signature);

        // Calculate USDC value
        // usdcValue = shares * nav / NAV_PRECISION
        uint256 grossUsdc = (shareAmount * navData.nav) / NAV_PRECISION;

        // Calculate 1% tax
        uint256 tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        uint256 netUsdc = grossUsdc - tax;

        // Check vault has enough USDC
        require(usdc.balanceOf(address(this)) >= grossUsdc, "Insufficient liquidity");

        // Burn shares
        _burn(msg.sender, shareAmount);

        // Update accounting (reduce wallet deposits proportionally)
        uint256 depositReduction = (walletDeposits[msg.sender] * shareAmount) / (balanceOf(msg.sender) + shareAmount);
        if (depositReduction > walletDeposits[msg.sender]) {
            depositReduction = walletDeposits[msg.sender];
        }
        walletDeposits[msg.sender] -= depositReduction;
        if (depositReduction > totalDeposited) {
            totalDeposited = 0;
        } else {
            totalDeposited -= depositReduction;
        }

        // Transfer tax to collector
        usdc.safeTransfer(taxCollector, tax);

        // Transfer net USDC to user
        usdc.safeTransfer(msg.sender, netUsdc);

        emit Withdraw(msg.sender, shareAmount, netUsdc, tax, navData.nav);
    }

    // ============================================
    // NAV Verification
    // ============================================

    /**
     * @notice Verify NAV signature and apply if valid
     * @param navData NAV data to verify
     * @param signature Signature from oracle
     */
    function _verifyAndApplyNav(NavData calldata navData, bytes calldata signature) internal {
        // Check deadline
        require(block.timestamp <= navData.deadline, "NAV expired");

        // Check age
        require(block.timestamp - navData.timestamp <= MAX_NAV_AGE, "NAV too old");

        // Check roundId is increasing (prevent replay)
        require(navData.roundId > lastRoundId, "RoundId must increase");

        // Verify signature
        bytes32 structHash = keccak256(abi.encode(
            NAV_TYPEHASH,
            navData.nav,
            navData.timestamp,
            navData.deadline,
            navData.roundId,
            address(this)
        ));
        bytes32 digest = structHash.toEthSignedMessageHash();
        address signer = digest.recover(signature);

        require(signer == navSigner, "Invalid NAV signer");

        // Check NAV change is reasonable (unless first update or small values)
        if (lastNav > 0 && navData.nav > 0) {
            uint256 diff = navData.nav > lastNav 
                ? navData.nav - lastNav 
                : lastNav - navData.nav;
            uint256 changePercent = (diff * 10000) / lastNav;
            require(changePercent <= MAX_NAV_CHANGE_BPS, "NAV change too large");
        }

        // Apply NAV
        lastNav = navData.nav;
        lastRoundId = navData.roundId;
        lastNavTimestamp = navData.timestamp;

        emit NavUpdated(navData.nav, navData.roundId, navData.timestamp);
    }

    /**
     * @notice Preview how many shares you'd get for a deposit
     * @param usdcAmount USDC amount (6 decimals)
     * @param nav NAV to use (1e18 scale)
     */
    function previewDeposit(uint256 usdcAmount, uint256 nav) external pure returns (uint256) {
        return (usdcAmount * NAV_PRECISION) / nav;
    }

    /**
     * @notice Preview how much USDC you'd get for redeeming (after 1% tax)
     * @param shareAmount Shares to redeem
     * @param nav NAV to use (1e18 scale)
     */
    function previewRedeem(uint256 shareAmount, uint256 nav) external pure returns (uint256 netUsdc, uint256 tax) {
        uint256 grossUsdc = (shareAmount * nav) / NAV_PRECISION;
        tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        netUsdc = grossUsdc - tax;
    }

    // ============================================
    // View Functions
    // ============================================

    /**
     * @notice Get current vault state
     */
    function getVaultState() external view returns (
        uint256 _lastNav,
        uint256 _lastRoundId,
        uint256 _lastNavTimestamp,
        uint256 _totalSupply,
        uint256 _vaultBalance,
        uint256 _totalDeposited,
        bool _paused
    ) {
        return (
            lastNav,
            lastRoundId,
            lastNavTimestamp,
            totalSupply(),
            usdc.balanceOf(address(this)),
            totalDeposited,
            paused
        );
    }

    /**
     * @notice Get user's position
     */
    function getUserPosition(address user) external view returns (
        uint256 shares,
        uint256 deposits,
        uint256 remainingCap
    ) {
        shares = balanceOf(user);
        deposits = walletDeposits[user];
        remainingCap = maxDepositPerWallet > deposits ? maxDepositPerWallet - deposits : 0;
    }

    // ============================================
    // Owner Functions
    // ============================================

    /**
     * @notice Update tax collector address
     */
    function setTaxCollector(address _taxCollector) external onlyOwner {
        require(_taxCollector != address(0), "Invalid address");
        emit TaxCollectorUpdated(taxCollector, _taxCollector);
        taxCollector = _taxCollector;
    }

    /**
     * @notice Update deposit caps
     */
    function setCaps(uint256 _maxPerWallet, uint256 _maxTotal) external onlyOwner {
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        emit CapsUpdated(_maxPerWallet, _maxTotal);
    }

    /**
     * @notice Pause/unpause vault
     */
    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    /**
     * @notice Emergency withdraw USDC to owner
     */
    function emergencyWithdraw(uint256 amount) external onlyOwner {
        require(amount <= usdc.balanceOf(address(this)), "Insufficient balance");
        usdc.safeTransfer(owner(), amount);
        emit EmergencyWithdraw(owner(), amount);
    }

    /**
     * @notice Force set lastNav (only for initialization/recovery)
     * @dev Use with caution - bypasses signature verification
     */
    function forceSetNav(uint256 _nav, uint256 _roundId) external onlyOwner {
        require(_nav > 0, "Invalid NAV");
        lastNav = _nav;
        lastRoundId = _roundId;
        lastNavTimestamp = block.timestamp;
        emit NavUpdated(_nav, _roundId, block.timestamp);
    }

    // ============================================
    // ERC20 Overrides
    // ============================================

    function decimals() public pure override returns (uint8) {
        return 18;
    }
}

contracts/PredictFiSniperVaultV5.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title PredictFiSniperVaultV5
 * @notice pSNIPER vault with async withdrawals and permissionless rebalancing
 * @dev 
 * 
 * Key V5 Features (Refined):
 * - Permissionless investIdle(): Anyone can rebalance idle funds to Polymarket
 * - Async Withdrawals: requestWithdraw → watchdog refills → claim
 * - Claim-time NAV: Users get current pro-rata value (simpler, no stored NAV)
 * - Signed NAV: Bot signs NAV off-chain, users include signature in tx
 * - 1% withdrawal tax to deployer
 * - Configurable per-wallet and total deposit caps
 * - Claim allowed even when paused (users can always exit)
 */
contract PredictFiSniperVaultV5 is ERC20, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ============================================
    // Constants
    // ============================================

    bytes32 public constant NAV_TYPEHASH = keccak256(
        "NavData(uint256 nav,uint256 timestamp,uint256 deadline,uint256 roundId,address vault)"
    );

    uint256 public constant MAX_NAV_AGE = 30;
    uint256 public constant MAX_NAV_CHANGE_BPS = 500;
    uint256 public constant WITHDRAWAL_TAX_BPS = 100;
    uint256 public constant USDC_DECIMALS = 6;
    uint256 public constant NAV_PRECISION = 1e18;

    uint256 public constant WITHDRAWAL_EXPIRY = 7 days;

    // ============================================
    // State Variables
    // ============================================

    IERC20 public immutable usdc;
    address public immutable navSigner;
    address public taxCollector;
    address public polymarketWallet;

    uint256 public lastNav;
    uint256 public lastRoundId;
    uint256 public lastNavTimestamp;

    uint256 public maxDepositPerWallet;
    uint256 public maxTotalDeposits;
    uint256 public totalDeposited;

    uint256 public targetBuffer;
    uint256 public maxRebalancePerCall;

    mapping(address => uint256) public walletDeposits;

    bool public paused;
    bool public depositsThrottled;

    // ============================================
    // Withdrawal Queue
    // ============================================

    struct WithdrawalRequest {
        address user;
        uint256 shares;
        uint256 requestTime;
        bool claimed;
    }

    WithdrawalRequest[] public withdrawalQueue;
    uint256 public nextWithdrawalIndex;
    uint256 public totalPendingShares;

    mapping(address => uint256[]) public userWithdrawals;

    // ============================================
    // Structs
    // ============================================

    struct NavData {
        uint256 nav;
        uint256 timestamp;
        uint256 deadline;
        uint256 roundId;
    }

    // ============================================
    // Events
    // ============================================

    event Deposit(
        address indexed user, 
        uint256 usdcAmount, 
        uint256 sharesReceived, 
        uint256 navUsed
    );

    event WithdrawalRequested(
        uint256 indexed requestId,
        address indexed user,
        uint256 shares
    );

    event WithdrawalClaimed(
        uint256 indexed requestId,
        address indexed user,
        uint256 shares,
        uint256 usdcReceived,
        uint256 taxPaid,
        uint256 navUsed
    );

    event WithdrawalCancelled(
        uint256 indexed requestId,
        address indexed user,
        uint256 sharesReturned
    );

    event BufferRefilled(uint256 amount, string source);
    event IdleFundsInvested(uint256 amount, address indexed caller);
    event NavUpdated(uint256 newNav, uint256 roundId, uint256 timestamp);
    event TaxCollectorUpdated(address indexed oldCollector, address indexed newCollector);
    event PolymarketWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event CapsUpdated(uint256 perWallet, uint256 total);
    event TargetBufferUpdated(uint256 oldBuffer, uint256 newBuffer);
    event MaxRebalanceUpdated(uint256 oldMax, uint256 newMax);
    event Paused(bool isPaused);
    event DepositsThrottled(bool isThrottled);
    event EmergencyWithdraw(address indexed to, uint256 amount);

    // ============================================
    // Constructor
    // ============================================

    constructor(
        address _usdc,
        address _navSigner,
        address _taxCollector,
        address _polymarketWallet,
        uint256 _initialNav,
        uint256 _maxPerWallet,
        uint256 _maxTotal,
        uint256 _targetBuffer,
        uint256 _maxRebalancePerCall
    ) ERC20("PredictFi Sniper", "pSNIPER") Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC");
        require(_navSigner != address(0), "Invalid signer");
        require(_taxCollector != address(0), "Invalid tax collector");
        require(_polymarketWallet != address(0), "Invalid PM wallet");
        require(_initialNav > 0, "Invalid initial NAV");

        usdc = IERC20(_usdc);
        navSigner = _navSigner;
        taxCollector = _taxCollector;
        polymarketWallet = _polymarketWallet;
        lastNav = _initialNav;
        lastRoundId = 0;
        lastNavTimestamp = block.timestamp;
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        targetBuffer = _targetBuffer;
        maxRebalancePerCall = _maxRebalancePerCall > 0 ? _maxRebalancePerCall : 1000e6; // Default 1000 USDC
    }

    // ============================================
    // Modifiers
    // ============================================

    modifier whenNotPaused() {
        require(!paused, "Vault is paused");
        _;
    }

    modifier whenDepositsNotThrottled() {
        require(!depositsThrottled, "Deposits throttled");
        _;
    }

    // ============================================
    // Core Functions
    // ============================================

    /**
     * @notice Deposit USDC and receive pSNIPE shares
     * @dev All USDC stays in vault; call investIdle() to rebalance
     * @param usdcAmount Amount of USDC to deposit (6 decimals)
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     */
    function deposit(
        uint256 usdcAmount,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused whenDepositsNotThrottled {
        require(usdcAmount > 0, "Amount must be > 0");

        _verifyAndApplyNav(navData, signature);

        require(walletDeposits[msg.sender] + usdcAmount <= maxDepositPerWallet, "Exceeds wallet cap");
        require(totalDeposited + usdcAmount <= maxTotalDeposits, "Exceeds total cap");

        uint256 sharesToMint = (usdcAmount * NAV_PRECISION) / navData.nav;
        require(sharesToMint > 0, "Shares too small");

        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);

        walletDeposits[msg.sender] += usdcAmount;
        totalDeposited += usdcAmount;

        _mint(msg.sender, sharesToMint);

        emit Deposit(msg.sender, usdcAmount, sharesToMint, navData.nav);
    }

    /**
     * @notice Permissionless: Send idle funds above targetBuffer to Polymarket
     * @dev Anyone can call this to rebalance the vault (blocked when paused)
     * @dev Rate-limited by maxRebalancePerCall to prevent drain attacks
     * @return amountSent Amount of USDC sent to Polymarket wallet
     */
    function investIdle() external nonReentrant whenNotPaused returns (uint256 amountSent) {
        uint256 balance = usdc.balanceOf(address(this));
        if (balance <= targetBuffer) return 0;

        uint256 idleFunds = balance - targetBuffer;
        // Rate limit: cap at maxRebalancePerCall per transaction
        amountSent = idleFunds > maxRebalancePerCall ? maxRebalancePerCall : idleFunds;

        usdc.safeTransfer(polymarketWallet, amountSent);

        emit IdleFundsInvested(amountSent, msg.sender);
    }

    /**
     * @notice Request withdrawal - shares are locked, USDC paid later
     * @param shareAmount Amount of pSNIPE shares to redeem
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     * @return requestId The withdrawal request ID
     */
    function requestWithdraw(
        uint256 shareAmount,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused returns (uint256 requestId) {
        require(shareAmount > 0, "Amount must be > 0");
        require(balanceOf(msg.sender) >= shareAmount, "Insufficient shares");

        _verifyAndApplyNav(navData, signature);

        _transfer(msg.sender, address(this), shareAmount);

        requestId = withdrawalQueue.length;
        withdrawalQueue.push(WithdrawalRequest({
            user: msg.sender,
            shares: shareAmount,
            requestTime: block.timestamp,
            claimed: false
        }));

        userWithdrawals[msg.sender].push(requestId);
        totalPendingShares += shareAmount;

        emit WithdrawalRequested(requestId, msg.sender, shareAmount);
    }

    /**
     * @notice Claim a pending withdrawal (after buffer is refilled)
     * @dev Uses claim-time NAV only (simpler, user gets current pro-rata share)
     * @dev Allowed even when paused - users can always exit
     * @param requestId The withdrawal request ID
     * @param navData Fresh signed NAV data
     * @param signature Oracle signature over navData
     */
    function claim(
        uint256 requestId,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage request = withdrawalQueue[requestId];

        require(request.user == msg.sender, "Not your request");
        require(!request.claimed, "Already claimed");
        require(block.timestamp <= request.requestTime + WITHDRAWAL_EXPIRY, "Request expired");

        _verifyAndApplyNav(navData, signature);

        uint256 grossUsdc = (request.shares * navData.nav) / NAV_PRECISION;
        uint256 tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        uint256 netUsdc = grossUsdc - tax;

        require(usdc.balanceOf(address(this)) >= grossUsdc, "Insufficient buffer");

        request.claimed = true;
        totalPendingShares -= request.shares;

        if (requestId == nextWithdrawalIndex) {
            while (nextWithdrawalIndex < withdrawalQueue.length && 
                   withdrawalQueue[nextWithdrawalIndex].claimed) {
                nextWithdrawalIndex++;
            }
        }

        _burn(address(this), request.shares);

        uint256 depositReduction = (walletDeposits[msg.sender] * request.shares) / 
            (balanceOf(msg.sender) + request.shares + 1);
        if (depositReduction > walletDeposits[msg.sender]) {
            depositReduction = walletDeposits[msg.sender];
        }
        walletDeposits[msg.sender] -= depositReduction;
        if (depositReduction > totalDeposited) {
            totalDeposited = 0;
        } else {
            totalDeposited -= depositReduction;
        }

        usdc.safeTransfer(taxCollector, tax);
        usdc.safeTransfer(msg.sender, netUsdc);

        emit WithdrawalClaimed(requestId, msg.sender, request.shares, netUsdc, tax, navData.nav);
    }

    /**
     * @notice Cancel an expired withdrawal request and get shares back
     * @param requestId The withdrawal request ID
     */
    function cancelExpiredWithdrawal(uint256 requestId) external nonReentrant {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage request = withdrawalQueue[requestId];

        require(request.user == msg.sender, "Not your request");
        require(!request.claimed, "Already claimed");
        require(block.timestamp > request.requestTime + WITHDRAWAL_EXPIRY, "Not expired yet");

        request.claimed = true;
        totalPendingShares -= request.shares;

        _transfer(address(this), msg.sender, request.shares);

        emit WithdrawalCancelled(requestId, msg.sender, request.shares);
    }

    // ============================================
    // NAV Verification
    // ============================================

    function _verifyAndApplyNav(NavData calldata navData, bytes calldata signature) internal {
        require(block.timestamp <= navData.deadline, "NAV expired");
        require(block.timestamp - navData.timestamp <= MAX_NAV_AGE, "NAV too old");
        require(navData.roundId > lastRoundId, "RoundId must increase");

        bytes32 structHash = keccak256(abi.encode(
            NAV_TYPEHASH,
            navData.nav,
            navData.timestamp,
            navData.deadline,
            navData.roundId,
            address(this)
        ));
        bytes32 digest = structHash.toEthSignedMessageHash();
        address signer = digest.recover(signature);

        require(signer == navSigner, "Invalid NAV signer");

        if (lastNav > 0 && navData.nav > 0) {
            uint256 diff = navData.nav > lastNav 
                ? navData.nav - lastNav 
                : lastNav - navData.nav;
            uint256 changePercent = (diff * 10000) / lastNav;
            require(changePercent <= MAX_NAV_CHANGE_BPS, "NAV change too large");
        }

        lastNav = navData.nav;
        lastRoundId = navData.roundId;
        lastNavTimestamp = navData.timestamp;

        emit NavUpdated(navData.nav, navData.roundId, navData.timestamp);
    }

    // ============================================
    // View Functions
    // ============================================

    function previewDeposit(uint256 usdcAmount, uint256 nav) external pure returns (uint256) {
        return (usdcAmount * NAV_PRECISION) / nav;
    }

    function previewRedeem(uint256 shareAmount, uint256 nav) external pure returns (uint256 netUsdc, uint256 tax) {
        uint256 grossUsdc = (shareAmount * nav) / NAV_PRECISION;
        tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        netUsdc = grossUsdc - tax;
    }

    function getIdleBalance() external view returns (uint256 idle, uint256 buffer) {
        buffer = usdc.balanceOf(address(this));
        idle = buffer > targetBuffer ? buffer - targetBuffer : 0;
    }

    function getVaultState() external view returns (
        uint256 _lastNav,
        uint256 _lastRoundId,
        uint256 _lastNavTimestamp,
        uint256 _totalSupply,
        uint256 _vaultBalance,
        uint256 _totalDeposited,
        uint256 _totalPendingShares,
        uint256 _pendingWithdrawalsCount,
        bool _paused,
        bool _depositsThrottled,
        uint256 _targetBuffer
    ) {
        uint256 pendingCount = 0;
        for (uint256 i = nextWithdrawalIndex; i < withdrawalQueue.length; i++) {
            if (!withdrawalQueue[i].claimed) pendingCount++;
        }

        return (
            lastNav,
            lastRoundId,
            lastNavTimestamp,
            totalSupply(),
            usdc.balanceOf(address(this)),
            totalDeposited,
            totalPendingShares,
            pendingCount,
            paused,
            depositsThrottled,
            targetBuffer
        );
    }

    function getPendingWithdrawalShares() external view returns (uint256) {
        return totalPendingShares;
    }

    function getUserWithdrawals(address user) external view returns (uint256[] memory) {
        return userWithdrawals[user];
    }

    function getWithdrawalRequest(uint256 requestId) external view returns (
        address user,
        uint256 shares,
        uint256 requestTime,
        bool claimed,
        bool expired
    ) {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage r = withdrawalQueue[requestId];
        return (
            r.user,
            r.shares,
            r.requestTime,
            r.claimed,
            block.timestamp > r.requestTime + WITHDRAWAL_EXPIRY
        );
    }

    function getRemainingAllowance(address wallet) external view returns (uint256) {
        if (walletDeposits[wallet] >= maxDepositPerWallet) return 0;
        return maxDepositPerWallet - walletDeposits[wallet];
    }

    // ============================================
    // Owner Functions
    // ============================================

    function refillBuffer(uint256 amount) external onlyOwner {
        usdc.safeTransferFrom(msg.sender, address(this), amount);
        emit BufferRefilled(amount, "owner");
    }

    function setTargetBuffer(uint256 _targetBuffer) external onlyOwner {
        emit TargetBufferUpdated(targetBuffer, _targetBuffer);
        targetBuffer = _targetBuffer;
    }

    function setMaxRebalancePerCall(uint256 _maxRebalancePerCall) external onlyOwner {
        require(_maxRebalancePerCall > 0, "Must be > 0");
        emit MaxRebalanceUpdated(maxRebalancePerCall, _maxRebalancePerCall);
        maxRebalancePerCall = _maxRebalancePerCall;
    }

    function setTaxCollector(address _taxCollector) external onlyOwner {
        require(_taxCollector != address(0), "Invalid address");
        emit TaxCollectorUpdated(taxCollector, _taxCollector);
        taxCollector = _taxCollector;
    }

    function setPolymarketWallet(address _polymarketWallet) external onlyOwner {
        require(_polymarketWallet != address(0), "Invalid address");
        emit PolymarketWalletUpdated(polymarketWallet, _polymarketWallet);
        polymarketWallet = _polymarketWallet;
    }

    function setCaps(uint256 _maxPerWallet, uint256 _maxTotal) external onlyOwner {
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        emit CapsUpdated(_maxPerWallet, _maxTotal);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function setDepositsThrottled(bool _throttled) external onlyOwner {
        depositsThrottled = _throttled;
        emit DepositsThrottled(_throttled);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid address");
        usdc.safeTransfer(to, amount);
        emit EmergencyWithdraw(to, amount);
    }
}

contracts/PredictFiSniperVaultV6.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title PredictFiSniperVaultV6
 * @notice pSNIPER vault with AUTO-SPLIT deposits
 * @dev 
 * 
 * Key V6 Feature: Auto-Split Deposits
 * - When user deposits $100, contract automatically:
 *   - Keeps 10% ($10) in vault buffer
 *   - Sends 90% ($90) directly to Polymarket Base deposit address
 * 
 * Other Features (from V5):
 * - Async Withdrawals: requestWithdraw → watchdog refills → claim
 * - Claim-time NAV: Users get current pro-rata value
 * - Signed NAV: Bot signs NAV off-chain, users include signature in tx
 * - 1% withdrawal tax to deployer
 * - Configurable per-wallet and total deposit caps
 * - Claim allowed even when paused (users can always exit)
 */
contract PredictFiSniperVaultV6 is ERC20, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ============================================
    // Constants
    // ============================================

    bytes32 public constant NAV_TYPEHASH = keccak256(
        "NavData(uint256 nav,uint256 timestamp,uint256 deadline,uint256 roundId,address vault)"
    );

    uint256 public constant MAX_NAV_AGE = 30;
    uint256 public constant MAX_NAV_CHANGE_BPS = 500;
    uint256 public constant WITHDRAWAL_TAX_BPS = 100;
    uint256 public constant USDC_DECIMALS = 6;
    uint256 public constant NAV_PRECISION = 1e18;

    uint256 public constant WITHDRAWAL_EXPIRY = 7 days;

    // Polymarket's official Base USDC deposit address
    // Verified: https://polymarket.com/portfolio (Transfer Crypto modal)
    address public constant POLYMARKET_BASE_DEPOSIT = 0xa76a91208FC7CB88420070AF978D12F440cab2F0;

    // ============================================
    // State Variables
    // ============================================

    IERC20 public immutable usdc;
    address public immutable navSigner;
    address public taxCollector;
    address public polymarketWallet; // Your PM trading wallet (for refills/tracking)

    uint256 public lastNav;
    uint256 public lastRoundId;
    uint256 public lastNavTimestamp;

    uint256 public maxDepositPerWallet;
    uint256 public maxTotalDeposits;
    uint256 public totalDeposited;

    // Buffer percentage in basis points (1000 = 10%, min 500, max 5000)
    uint256 public bufferPercentBps;

    mapping(address => uint256) public walletDeposits;

    bool public paused;
    bool public depositsThrottled;

    // Track total sent to Polymarket
    uint256 public totalSentToPolymarket;

    // ============================================
    // Withdrawal Queue
    // ============================================

    struct WithdrawalRequest {
        address user;
        uint256 shares;
        uint256 requestTime;
        bool claimed;
    }

    WithdrawalRequest[] public withdrawalQueue;
    uint256 public nextWithdrawalIndex;
    uint256 public totalPendingShares;

    mapping(address => uint256[]) public userWithdrawals;

    // ============================================
    // Structs
    // ============================================

    struct NavData {
        uint256 nav;
        uint256 timestamp;
        uint256 deadline;
        uint256 roundId;
    }

    // ============================================
    // Events
    // ============================================

    event Deposit(
        address indexed user, 
        uint256 usdcAmount, 
        uint256 sharesReceived, 
        uint256 navUsed,
        uint256 toBuffer,
        uint256 toPolymarket
    );

    event WithdrawalRequested(
        uint256 indexed requestId,
        address indexed user,
        uint256 shares
    );

    event WithdrawalClaimed(
        uint256 indexed requestId,
        address indexed user,
        uint256 shares,
        uint256 usdcReceived,
        uint256 taxPaid,
        uint256 navUsed
    );

    event WithdrawalCancelled(
        uint256 indexed requestId,
        address indexed user,
        uint256 sharesReturned
    );

    event BufferRefilled(uint256 amount, string source);
    event NavUpdated(uint256 newNav, uint256 roundId, uint256 timestamp);
    event TaxCollectorUpdated(address indexed oldCollector, address indexed newCollector);
    event PolymarketWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event CapsUpdated(uint256 perWallet, uint256 total);
    event BufferPercentUpdated(uint256 oldPercent, uint256 newPercent);
    event Paused(bool isPaused);
    event DepositsThrottled(bool isThrottled);
    event EmergencyWithdraw(address indexed to, uint256 amount);

    // ============================================
    // Constructor
    // ============================================

    constructor(
        address _usdc,
        address _navSigner,
        address _taxCollector,
        address _polymarketWallet,
        uint256 _initialNav,
        uint256 _maxPerWallet,
        uint256 _maxTotal,
        uint256 _bufferPercentBps  // e.g., 1000 = 10% (min 500, max 5000)
    ) ERC20("PredictFi Sniper", "pSNIPER") Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC");
        require(_navSigner != address(0), "Invalid signer");
        require(_taxCollector != address(0), "Invalid tax collector");
        require(_polymarketWallet != address(0), "Invalid PM wallet");
        require(_initialNav > 0, "Invalid initial NAV");
        require(_bufferPercentBps >= 500 && _bufferPercentBps <= 5000, "Buffer must be 5-50%");

        usdc = IERC20(_usdc);
        navSigner = _navSigner;
        taxCollector = _taxCollector;
        polymarketWallet = _polymarketWallet;
        lastNav = _initialNav;
        lastRoundId = 0;
        lastNavTimestamp = block.timestamp;
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        bufferPercentBps = _bufferPercentBps;
    }

    // ============================================
    // Modifiers
    // ============================================

    modifier whenNotPaused() {
        require(!paused, "Vault is paused");
        _;
    }

    modifier whenDepositsNotThrottled() {
        require(!depositsThrottled, "Deposits throttled");
        _;
    }

    // ============================================
    // Core Functions
    // ============================================

    /**
     * @notice Deposit USDC and receive pSNIPE shares
     * @dev AUTO-SPLIT: bufferPercentBps% stays in vault, rest goes to Polymarket
     * @param usdcAmount Amount of USDC to deposit (6 decimals)
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     */
    function deposit(
        uint256 usdcAmount,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused whenDepositsNotThrottled {
        require(usdcAmount > 0, "Amount must be > 0");

        _verifyAndApplyNav(navData, signature);

        require(walletDeposits[msg.sender] + usdcAmount <= maxDepositPerWallet, "Exceeds wallet cap");
        require(totalDeposited + usdcAmount <= maxTotalDeposits, "Exceeds total cap");

        uint256 sharesToMint = (usdcAmount * NAV_PRECISION) / navData.nav;
        require(sharesToMint > 0, "Shares too small");

        // Transfer full amount from user to this contract first
        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);

        // Calculate split: bufferPercentBps% stays, rest to Polymarket
        uint256 toBuffer = (usdcAmount * bufferPercentBps) / 10000;
        uint256 toPolymarket = usdcAmount - toBuffer;

        // Send portion to Polymarket Base deposit address
        if (toPolymarket > 0) {
            usdc.safeTransfer(POLYMARKET_BASE_DEPOSIT, toPolymarket);
            totalSentToPolymarket += toPolymarket;
        }

        // Update tracking
        walletDeposits[msg.sender] += usdcAmount;
        totalDeposited += usdcAmount;

        _mint(msg.sender, sharesToMint);

        emit Deposit(msg.sender, usdcAmount, sharesToMint, navData.nav, toBuffer, toPolymarket);
    }

    /**
     * @notice Request withdrawal - shares are locked, USDC paid later
     * @param shareAmount Amount of pSNIPE shares to redeem
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     * @return requestId The withdrawal request ID
     */
    function requestWithdraw(
        uint256 shareAmount,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused returns (uint256 requestId) {
        require(shareAmount > 0, "Amount must be > 0");
        require(balanceOf(msg.sender) >= shareAmount, "Insufficient shares");

        _verifyAndApplyNav(navData, signature);

        _transfer(msg.sender, address(this), shareAmount);

        requestId = withdrawalQueue.length;
        withdrawalQueue.push(WithdrawalRequest({
            user: msg.sender,
            shares: shareAmount,
            requestTime: block.timestamp,
            claimed: false
        }));

        userWithdrawals[msg.sender].push(requestId);
        totalPendingShares += shareAmount;

        emit WithdrawalRequested(requestId, msg.sender, shareAmount);
    }

    /**
     * @notice Claim a pending withdrawal (after buffer is refilled by keeper)
     * @dev Uses claim-time NAV only (simpler, user gets current pro-rata share)
     * @dev Allowed even when paused - users can always exit
     * @param requestId The withdrawal request ID
     * @param navData Fresh signed NAV data
     * @param signature Oracle signature over navData
     */
    function claim(
        uint256 requestId,
        NavData calldata navData,
        bytes calldata signature
    ) external nonReentrant {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage request = withdrawalQueue[requestId];

        require(request.user == msg.sender, "Not your request");
        require(!request.claimed, "Already claimed");
        require(block.timestamp <= request.requestTime + WITHDRAWAL_EXPIRY, "Request expired");

        _verifyAndApplyNav(navData, signature);

        uint256 grossUsdc = (request.shares * navData.nav) / NAV_PRECISION;
        uint256 tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        uint256 netUsdc = grossUsdc - tax;

        require(usdc.balanceOf(address(this)) >= grossUsdc, "Insufficient buffer");

        request.claimed = true;
        totalPendingShares -= request.shares;

        if (requestId == nextWithdrawalIndex) {
            while (nextWithdrawalIndex < withdrawalQueue.length && 
                   withdrawalQueue[nextWithdrawalIndex].claimed) {
                nextWithdrawalIndex++;
            }
        }

        _burn(address(this), request.shares);

        uint256 depositReduction = (walletDeposits[msg.sender] * request.shares) / 
            (balanceOf(msg.sender) + request.shares + 1);
        if (depositReduction > walletDeposits[msg.sender]) {
            depositReduction = walletDeposits[msg.sender];
        }
        walletDeposits[msg.sender] -= depositReduction;
        if (depositReduction > totalDeposited) {
            totalDeposited = 0;
        } else {
            totalDeposited -= depositReduction;
        }

        usdc.safeTransfer(taxCollector, tax);
        usdc.safeTransfer(msg.sender, netUsdc);

        emit WithdrawalClaimed(requestId, msg.sender, request.shares, netUsdc, tax, navData.nav);
    }

    /**
     * @notice Cancel an expired withdrawal request and get shares back
     * @param requestId The withdrawal request ID
     */
    function cancelExpiredWithdrawal(uint256 requestId) external nonReentrant {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage request = withdrawalQueue[requestId];

        require(request.user == msg.sender, "Not your request");
        require(!request.claimed, "Already claimed");
        require(block.timestamp > request.requestTime + WITHDRAWAL_EXPIRY, "Not expired yet");

        request.claimed = true;
        totalPendingShares -= request.shares;

        _transfer(address(this), msg.sender, request.shares);

        emit WithdrawalCancelled(requestId, msg.sender, request.shares);
    }

    // ============================================
    // NAV Verification
    // ============================================

    function _verifyAndApplyNav(NavData calldata navData, bytes calldata signature) internal {
        require(block.timestamp <= navData.deadline, "NAV expired");
        require(block.timestamp - navData.timestamp <= MAX_NAV_AGE, "NAV too old");
        require(navData.roundId > lastRoundId, "RoundId must increase");

        bytes32 structHash = keccak256(abi.encode(
            NAV_TYPEHASH,
            navData.nav,
            navData.timestamp,
            navData.deadline,
            navData.roundId,
            address(this)
        ));
        bytes32 digest = structHash.toEthSignedMessageHash();
        address signer = digest.recover(signature);

        require(signer == navSigner, "Invalid NAV signer");

        if (lastNav > 0 && navData.nav > 0) {
            uint256 diff = navData.nav > lastNav 
                ? navData.nav - lastNav 
                : lastNav - navData.nav;
            uint256 changePercent = (diff * 10000) / lastNav;
            require(changePercent <= MAX_NAV_CHANGE_BPS, "NAV change too large");
        }

        lastNav = navData.nav;
        lastRoundId = navData.roundId;
        lastNavTimestamp = navData.timestamp;

        emit NavUpdated(navData.nav, navData.roundId, navData.timestamp);
    }

    // ============================================
    // View Functions
    // ============================================

    function previewDeposit(uint256 usdcAmount, uint256 nav) external view returns (
        uint256 shares, 
        uint256 toBuffer, 
        uint256 toPolymarket
    ) {
        shares = (usdcAmount * NAV_PRECISION) / nav;
        toBuffer = (usdcAmount * bufferPercentBps) / 10000;
        toPolymarket = usdcAmount - toBuffer;
    }

    function previewRedeem(uint256 shareAmount, uint256 nav) external pure returns (uint256 netUsdc, uint256 tax) {
        uint256 grossUsdc = (shareAmount * nav) / NAV_PRECISION;
        tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        netUsdc = grossUsdc - tax;
    }

    function getVaultState() external view returns (
        uint256 _lastNav,
        uint256 _lastRoundId,
        uint256 _lastNavTimestamp,
        uint256 _totalSupply,
        uint256 _vaultBalance,
        uint256 _totalDeposited,
        uint256 _totalPendingShares,
        uint256 _pendingWithdrawalsCount,
        bool _paused,
        bool _depositsThrottled,
        uint256 _bufferPercentBps,
        uint256 _totalSentToPolymarket
    ) {
        uint256 pendingCount = 0;
        for (uint256 i = nextWithdrawalIndex; i < withdrawalQueue.length; i++) {
            if (!withdrawalQueue[i].claimed) pendingCount++;
        }

        return (
            lastNav,
            lastRoundId,
            lastNavTimestamp,
            totalSupply(),
            usdc.balanceOf(address(this)),
            totalDeposited,
            totalPendingShares,
            pendingCount,
            paused,
            depositsThrottled,
            bufferPercentBps,
            totalSentToPolymarket
        );
    }

    function getPendingWithdrawalShares() external view returns (uint256) {
        return totalPendingShares;
    }

    function getUserWithdrawals(address user) external view returns (uint256[] memory) {
        return userWithdrawals[user];
    }

    function getWithdrawalRequest(uint256 requestId) external view returns (
        address user,
        uint256 shares,
        uint256 requestTime,
        bool claimed,
        bool expired
    ) {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage r = withdrawalQueue[requestId];
        return (
            r.user,
            r.shares,
            r.requestTime,
            r.claimed,
            block.timestamp > r.requestTime + WITHDRAWAL_EXPIRY
        );
    }

    function getRemainingAllowance(address wallet) external view returns (uint256) {
        if (walletDeposits[wallet] >= maxDepositPerWallet) return 0;
        return maxDepositPerWallet - walletDeposits[wallet];
    }

    // ============================================
    // Owner Functions
    // ============================================

    function refillBuffer(uint256 amount) external onlyOwner {
        usdc.safeTransferFrom(msg.sender, address(this), amount);
        emit BufferRefilled(amount, "owner");
    }

    function setBufferPercent(uint256 _bufferPercentBps) external onlyOwner {
        require(_bufferPercentBps >= 500 && _bufferPercentBps <= 5000, "Buffer must be 5-50%");
        emit BufferPercentUpdated(bufferPercentBps, _bufferPercentBps);
        bufferPercentBps = _bufferPercentBps;
    }

    function setTaxCollector(address _taxCollector) external onlyOwner {
        require(_taxCollector != address(0), "Invalid address");
        emit TaxCollectorUpdated(taxCollector, _taxCollector);
        taxCollector = _taxCollector;
    }

    function setPolymarketWallet(address _polymarketWallet) external onlyOwner {
        require(_polymarketWallet != address(0), "Invalid address");
        emit PolymarketWalletUpdated(polymarketWallet, _polymarketWallet);
        polymarketWallet = _polymarketWallet;
    }

    function setCaps(uint256 _maxPerWallet, uint256 _maxTotal) external onlyOwner {
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        emit CapsUpdated(_maxPerWallet, _maxTotal);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function setDepositsThrottled(bool _throttled) external onlyOwner {
        depositsThrottled = _throttled;
        emit DepositsThrottled(_throttled);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid address");
        usdc.safeTransfer(to, amount);
        emit EmergencyWithdraw(to, amount);
    }
}

contracts/PredictFiSniperVaultV7.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title PredictFiSniperVaultV7
 * @notice pSNIPER vault with 100% Polymarket forwarding and 3-state asset tracking
 * @dev 
 * 
 * V7 Architecture: 3-State Asset Tracking with Conservation Bounds
 * 
 * Asset States:
 * 1. inFlightOnChain - USDC at Polymarket deposit address (usually ~0 after sweep)
 * 2. pendingCredit - Forwarded but not yet visible in PM API (during bridge)
 * 3. creditedAssets - PM cash + positions visible via API
 * 
 * Key Changes from V6:
 * - 100% forwarding to Polymarket (no buffer split)
 * - Conservation-style bounds replace 5% NAV change limit
 * - Extended NavData with full asset breakdown
 * - Pausable deposits with safety valves
 * - All withdrawals are queued (no buffer)
 * 
 * Safety Features:
 * - Conservation bound: totalAssets >= expectedAssets * (1 - maxLossBps)
 * - 30-second signature validity
 * - Monotonically increasing roundId
 * - No withdrawal tax (0%)
 * - Total vault deposit cap (no per-wallet limit)
 * - Pausable on safety valve triggers
 */
contract PredictFiSniperVaultV7 is ERC20, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ============================================
    // Constants
    // ============================================

    bytes32 public constant NAV_TYPEHASH = keccak256(
        "NavDataV7(uint256 totalAssets,uint256 creditedCash,uint256 creditedPositions,uint256 pendingCredit,uint256 inFlightOnChain,uint256 timestamp,uint256 deadline,uint256 roundId,address vault,uint256 chainId,bytes32 domainSalt)"
    );

    // Domain salt for pseudo EIP-712 separation
    bytes32 public constant DOMAIN_SALT = keccak256("PredictFiSniperVaultV7.v1");

    uint256 public constant MAX_NAV_AGE = 300;  // 5 minutes for MVP (bot takes 30-120s)
    uint256 public constant MIN_NAV_INTERVAL = 60;  // Min 60s between NAV updates
    uint256 public constant STALE_NAV_GRACE = 900;  // 15 min grace for deposits/withdrawRequests
    uint256 public constant WITHDRAWAL_TAX_BPS = 0;  // No withdrawal tax
    uint256 public constant USDC_DECIMALS = 6;
    uint256 public constant NAV_PRECISION = 1e18;
    uint256 public constant WITHDRAWAL_EXPIRY = 7 days;

    // Pending ratio thresholds
    uint256 public constant PENDING_RATIO_PAUSE = 3000;   // 30% - pause deposits
    uint256 public constant PENDING_RATIO_CAP = 1000;     // 10% - cap single deposit
    uint256 public constant MAX_DEPOSIT_DURING_LIMBO = 1000 * 1e6;  // $1000 max during limbo
    uint256 public constant CLAIM_SLIPPAGE_BPS = 50;  // 0.5% slippage tolerance for bridge fees

    // Polymarket's official Base USDC deposit address (new wallet)
    address public constant POLYMARKET_BASE_DEPOSIT = 0x2b20920A00D705043260eBFE6561bC96FBd84dBE;

    // ============================================
    // State Variables
    // ============================================

    IERC20 public immutable usdc;
    address public immutable navSigner;
    address public taxCollector;
    address public polymarketWallet;

    uint256 public lastRoundId;
    uint256 public lastNavTimestamp;

    uint256 public maxDepositPerWallet;
    uint256 public maxTotalDeposits;

    // Conservation tracking
    uint256 public expectedAssets;      // Sum of all deposits minus withdrawals paid
    uint256 public maxLossBps;          // Max allowed loss from expected (e.g., 1000 = 10%)

    // Deposit tracking for pendingCredit reconciliation
    uint256 public totalForwardedToPolymarket;  // Total USDC sent to PM deposit address

    // Correction tracking for auditability
    uint256 public correctionNonce;     // Increments on each manual correction

    // Last accepted NAV for stale grace period
    uint256 public lastAcceptedTotalAssets;
    uint256 public lastAcceptedTimestamp;

    mapping(address => uint256) public walletDeposits;

    bool public paused;
    bool public depositsThrottled;

    // ============================================
    // Withdrawal Queue
    // ============================================

    struct WithdrawalRequest {
        address user;
        uint256 shares;
        uint256 usdcLocked;     // V7.3: USDC amount locked at request time (price fixed)
        uint256 requestTime;
        bool claimed;
    }

    WithdrawalRequest[] public withdrawalQueue;
    uint256 public nextWithdrawalIndex;
    uint256 public totalPendingShares;

    mapping(address => uint256[]) public userWithdrawals;

    // ============================================
    // Structs
    // ============================================

    struct NavDataV7 {
        uint256 totalAssets;        // Sum of all asset states
        uint256 creditedCash;       // PM cash balance (from API)
        uint256 creditedPositions;  // PM positions liquidation value (from API)
        uint256 pendingCredit;      // Forwarded but not yet credited
        uint256 inFlightOnChain;    // USDC at deposit address
        uint256 timestamp;
        uint256 deadline;
        uint256 roundId;
    }

    // ============================================
    // Events
    // ============================================

    event Deposit(
        address indexed user, 
        uint256 usdcAmount, 
        uint256 sharesReceived, 
        uint256 navUsed
    );

    event WithdrawalRequested(
        uint256 indexed requestId,
        address indexed user,
        uint256 shares,
        uint256 expectedUsdc
    );

    event WithdrawalClaimed(
        uint256 indexed requestId,
        address indexed user,
        uint256 shares,
        uint256 usdcReceived,
        uint256 taxPaid,
        uint256 navUsed
    );

    event WithdrawalCancelled(
        uint256 indexed requestId,
        address indexed user,
        uint256 sharesReturned
    );

    event NavUpdated(
        uint256 totalAssets,
        uint256 creditedCash,
        uint256 creditedPositions,
        uint256 pendingCredit,
        uint256 roundId,
        uint256 timestamp
    );

    event BufferRefilled(uint256 amount, string source);
    event TaxCollectorUpdated(address indexed oldCollector, address indexed newCollector);
    event PolymarketWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event CapsUpdated(uint256 perWallet, uint256 total);
    event MaxLossUpdated(uint256 oldMaxLoss, uint256 newMaxLoss);
    event Paused(bool isPaused);
    event DepositsThrottled(bool isThrottled);
    event EmergencyWithdraw(address indexed to, uint256 amount);

    // Correction events for auditability
    event CorrectionExpectedAssets(
        uint256 indexed nonce,
        uint256 oldValue,
        uint256 newValue,
        string reason
    );
    event CorrectionTotalForwarded(
        uint256 indexed nonce,
        uint256 oldValue,
        uint256 newValue,
        string reason
    );
    event CorrectionTradingLoss(
        uint256 indexed nonce,
        uint256 lossAmount,
        uint256 oldExpected,
        uint256 newExpected
    );
    event CorrectionTradingGain(
        uint256 indexed nonce,
        uint256 gainAmount,
        uint256 oldExpected,
        uint256 newExpected
    );

    // ============================================
    // Constructor
    // ============================================

    constructor(
        address _usdc,
        address _navSigner,
        address _taxCollector,
        address _polymarketWallet,
        uint256 _maxPerWallet,
        uint256 _maxTotal,
        uint256 _maxLossBps  // e.g., 1000 = 10% max loss allowed
    ) ERC20("PredictFi Sniper", "pSNIPER") Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC");
        require(_navSigner != address(0), "Invalid signer");
        require(_taxCollector != address(0), "Invalid tax collector");
        require(_polymarketWallet != address(0), "Invalid PM wallet");
        require(_maxLossBps <= 5000, "Max loss cannot exceed 50%");

        usdc = IERC20(_usdc);
        navSigner = _navSigner;
        taxCollector = _taxCollector;
        polymarketWallet = _polymarketWallet;
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        maxLossBps = _maxLossBps;

        lastRoundId = 0;
        lastNavTimestamp = 0;  // Initialize to 0 to allow first NAV update
        expectedAssets = 0;
        totalForwardedToPolymarket = 0;
    }

    // ============================================
    // Modifiers
    // ============================================

    modifier whenNotPaused() {
        require(!paused, "Vault is paused");
        _;
    }

    modifier whenPaused() {
        require(paused, "Vault must be paused");
        _;
    }

    modifier whenDepositsNotThrottled() {
        require(!depositsThrottled, "Deposits throttled");
        _;
    }

    // ============================================
    // Core Functions
    // ============================================

    /**
     * @notice Deposit USDC and receive pSNIPER shares
     * @dev 100% of deposit goes to Polymarket Base deposit address
     * @param usdcAmount Amount of USDC to deposit (6 decimals)
     * @param navData Signed NAV data with full asset breakdown
     * @param signature Oracle signature over navData
     */
    function deposit(
        uint256 usdcAmount,
        NavDataV7 calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused whenDepositsNotThrottled {
        require(usdcAmount > 0, "Amount must be > 0");

        _verifyAndApplyNav(navData, signature);

        // Per-wallet cap removed - only total vault cap enforced
        require(expectedAssets + usdcAmount <= maxTotalDeposits, "Exceeds total cap");

        // Limbo cap: if pendingCredit > 10% of totalAssets, cap single deposit to $1000
        if (navData.totalAssets > 0) {
            uint256 pendingRatioBps = (navData.pendingCredit * 10000) / navData.totalAssets;
            if (pendingRatioBps > PENDING_RATIO_CAP) {
                require(usdcAmount <= MAX_DEPOSIT_DURING_LIMBO, "Deposit capped during limbo");
            }
        }

        // Calculate NAV per share
        uint256 nav = _calculateNav(navData.totalAssets);

        uint256 sharesToMint = (usdcAmount * NAV_PRECISION) / nav;
        require(sharesToMint > 0, "Shares too small");

        // Transfer USDC from user
        usdc.safeTransferFrom(msg.sender, address(this), usdcAmount);

        // Forward 100% to Polymarket Base deposit address
        usdc.safeTransfer(POLYMARKET_BASE_DEPOSIT, usdcAmount);
        totalForwardedToPolymarket += usdcAmount;

        // Update conservation tracking
        expectedAssets += usdcAmount;
        walletDeposits[msg.sender] += usdcAmount;

        _mint(msg.sender, sharesToMint);

        emit Deposit(msg.sender, usdcAmount, sharesToMint, nav);
    }

    /**
     * @notice Request withdrawal - shares are locked, USDC amount fixed at request time
     * @dev V7.3: Price is locked at request time. User gets exactly usdcLocked at claim.
     * @param shareAmount Amount of pSNIPER shares to redeem
     * @param navData Signed NAV data from oracle
     * @param signature Oracle signature over navData
     * @return requestId The withdrawal request ID
     */
    function requestWithdraw(
        uint256 shareAmount,
        NavDataV7 calldata navData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused returns (uint256 requestId) {
        require(shareAmount > 0, "Amount must be > 0");
        require(balanceOf(msg.sender) >= shareAmount, "Insufficient shares");

        _verifyAndApplyNav(navData, signature);

        // V7.3: Calculate and LOCK the USDC amount at current NAV
        // This price is fixed - user will receive exactly this amount at claim
        uint256 nav = _calculateNav(navData.totalAssets);
        uint256 usdcLocked = (shareAmount * nav) / NAV_PRECISION;

        // Lock shares in contract
        _transfer(msg.sender, address(this), shareAmount);

        requestId = withdrawalQueue.length;
        withdrawalQueue.push(WithdrawalRequest({
            user: msg.sender,
            shares: shareAmount,
            usdcLocked: usdcLocked,    // V7.3: Store locked amount
            requestTime: block.timestamp,
            claimed: false
        }));

        userWithdrawals[msg.sender].push(requestId);
        totalPendingShares += shareAmount;

        emit WithdrawalRequested(requestId, msg.sender, shareAmount, usdcLocked);
    }

    /**
     * @notice Claim a pending withdrawal (after keeper refills vault buffer)
     * @dev V7.3: Uses locked price from request time - no NAV re-verification needed
     * @dev Allowed even when paused - users can always exit
     * @param requestId The withdrawal request ID
     */
    function claim(
        uint256 requestId
    ) external nonReentrant {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage request = withdrawalQueue[requestId];

        require(request.user == msg.sender, "Not your request");
        require(!request.claimed, "Already claimed");
        require(block.timestamp <= request.requestTime + WITHDRAWAL_EXPIRY, "Request expired");

        // V7.3.3: Invalidate any cached NAV signatures to prevent stale pricing
        // This fixes the race condition where deposit+claim can use same roundId
        lastRoundId += 1;

        // V7.3: Use locked USDC amount from request time - no NAV recalculation
        uint256 grossUsdc = request.usdcLocked;
        uint256 vaultBalance = usdc.balanceOf(address(this));

        // V7.3.1: Allow 0.5% slippage for bridge/relay fees
        uint256 minRequired = grossUsdc - (grossUsdc * CLAIM_SLIPPAGE_BPS) / 10000;
        require(vaultBalance >= minRequired, "Not enough USDC in buffer. Try again later when positions are liquidated.");

        // Pay out actual available (capped at locked amount)
        uint256 actualGross = vaultBalance >= grossUsdc ? grossUsdc : vaultBalance;
        uint256 tax = (actualGross * WITHDRAWAL_TAX_BPS) / 10000;
        uint256 netUsdc = actualGross - tax;

        request.claimed = true;
        totalPendingShares -= request.shares;

        // Advance queue index
        if (requestId == nextWithdrawalIndex) {
            while (nextWithdrawalIndex < withdrawalQueue.length && 
                   withdrawalQueue[nextWithdrawalIndex].claimed) {
                nextWithdrawalIndex++;
            }
        }

        // Burn the locked shares
        _burn(address(this), request.shares);

        // Update conservation tracking (use locked amount, not actual payout, to maintain invariant)
        if (grossUsdc > expectedAssets) {
            expectedAssets = 0;
        } else {
            expectedAssets -= grossUsdc;
        }

        // Reduce wallet deposit tracking
        uint256 depositReduction = (walletDeposits[msg.sender] * request.shares) / 
            (balanceOf(msg.sender) + request.shares + 1);
        if (depositReduction > walletDeposits[msg.sender]) {
            depositReduction = walletDeposits[msg.sender];
        }
        walletDeposits[msg.sender] -= depositReduction;

        // Transfer USDC
        usdc.safeTransfer(taxCollector, tax);
        usdc.safeTransfer(msg.sender, netUsdc);

        // V7.3: Calculate effective NAV from locked values for backward-compatible event
        uint256 effectiveNav = (grossUsdc * NAV_PRECISION) / request.shares;
        emit WithdrawalClaimed(requestId, msg.sender, request.shares, netUsdc, tax, effectiveNav);
    }

    /**
     * @notice Cancel an expired withdrawal request and get shares back
     * @param requestId The withdrawal request ID
     */
    function cancelExpiredWithdrawal(uint256 requestId) external nonReentrant {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage request = withdrawalQueue[requestId];

        require(request.user == msg.sender, "Not your request");
        require(!request.claimed, "Already claimed");
        require(block.timestamp > request.requestTime + WITHDRAWAL_EXPIRY, "Not expired yet");

        request.claimed = true;
        totalPendingShares -= request.shares;

        // Return shares to user
        _transfer(address(this), msg.sender, request.shares);

        emit WithdrawalCancelled(requestId, msg.sender, request.shares);
    }

    // ============================================
    // NAV Verification
    // ============================================

    function _verifyAndApplyNav(NavDataV7 calldata navData, bytes calldata signature) internal {
        require(block.timestamp <= navData.deadline, "NAV expired");
        require(block.timestamp - navData.timestamp <= MAX_NAV_AGE, "NAV too old");
        require(navData.roundId > lastRoundId, "RoundId must increase");

        // Enforce minimum interval between NAV updates (prevents rapid spam)
        require(navData.timestamp >= lastNavTimestamp + MIN_NAV_INTERVAL || lastNavTimestamp == 0, 
                "NAV update too frequent");

        // Verify asset breakdown adds up
        uint256 computedTotal = navData.creditedCash + navData.creditedPositions + 
                                navData.pendingCredit + navData.inFlightOnChain;
        require(computedTotal == navData.totalAssets, "Asset breakdown mismatch");

        // Verify signature (includes chainId and domainSalt for domain separation)
        bytes32 structHash = keccak256(abi.encode(
            NAV_TYPEHASH,
            navData.totalAssets,
            navData.creditedCash,
            navData.creditedPositions,
            navData.pendingCredit,
            navData.inFlightOnChain,
            navData.timestamp,
            navData.deadline,
            navData.roundId,
            address(this),
            block.chainid,
            DOMAIN_SALT
        ));
        bytes32 digest = structHash.toEthSignedMessageHash();
        address signer = digest.recover(signature);

        require(signer == navSigner, "Invalid NAV signer");

        // Conservation bound check (only if we have deposits)
        if (expectedAssets > 0 && totalSupply() > 0) {
            uint256 minAllowedAssets = (expectedAssets * (10000 - maxLossBps)) / 10000;
            require(navData.totalAssets >= minAllowedAssets, "Conservation bound violated");
        }

        lastRoundId = navData.roundId;
        lastNavTimestamp = navData.timestamp;

        // Store for stale NAV grace period
        lastAcceptedTotalAssets = navData.totalAssets;
        lastAcceptedTimestamp = block.timestamp;

        emit NavUpdated(
            navData.totalAssets,
            navData.creditedCash,
            navData.creditedPositions,
            navData.pendingCredit,
            navData.roundId,
            navData.timestamp
        );
    }

    function _calculateNav(uint256 totalAssets) internal view returns (uint256) {
        uint256 supply = totalSupply();
        if (supply == 0) {
            // Initial NAV: $1.00 per share = 1e6 (USDC decimals)
            return 10**6;
        }
        // NAV = totalAssets_6dec * 1e18 / supply_18dec
        return (totalAssets * NAV_PRECISION) / supply;
    }

    // ============================================
    // View Functions
    // ============================================

    function previewDeposit(uint256 usdcAmount, uint256 totalAssets) external view returns (uint256 shares) {
        uint256 nav = _calculateNav(totalAssets);
        shares = (usdcAmount * NAV_PRECISION) / nav;
    }

    function previewRedeem(uint256 shareAmount, uint256 totalAssets) external view returns (uint256 netUsdc, uint256 tax) {
        uint256 nav = _calculateNav(totalAssets);
        uint256 grossUsdc = (shareAmount * nav) / NAV_PRECISION;
        tax = (grossUsdc * WITHDRAWAL_TAX_BPS) / 10000;
        netUsdc = grossUsdc - tax;
    }

    function getVaultState() external view returns (
        uint256 _lastRoundId,
        uint256 _lastNavTimestamp,
        uint256 _totalSupply,
        uint256 _vaultBuffer,
        uint256 _expectedAssets,
        uint256 _totalForwarded,
        uint256 _totalPendingShares,
        uint256 _pendingWithdrawalsCount,
        bool _paused,
        bool _depositsThrottled,
        uint256 _maxLossBps
    ) {
        uint256 pendingCount = 0;
        for (uint256 i = nextWithdrawalIndex; i < withdrawalQueue.length; i++) {
            if (!withdrawalQueue[i].claimed) pendingCount++;
        }

        return (
            lastRoundId,
            lastNavTimestamp,
            totalSupply(),
            usdc.balanceOf(address(this)),
            expectedAssets,
            totalForwardedToPolymarket,
            totalPendingShares,
            pendingCount,
            paused,
            depositsThrottled,
            maxLossBps
        );
    }

    function getPendingWithdrawalShares() external view returns (uint256) {
        return totalPendingShares;
    }

    function getUserWithdrawals(address user) external view returns (uint256[] memory) {
        return userWithdrawals[user];
    }

    function getWithdrawalRequest(uint256 requestId) external view returns (
        address user,
        uint256 shares,
        uint256 usdcLocked,
        uint256 requestTime,
        bool claimed,
        bool expired
    ) {
        require(requestId < withdrawalQueue.length, "Invalid request");
        WithdrawalRequest storage r = withdrawalQueue[requestId];
        return (
            r.user,
            r.shares,
            r.usdcLocked,
            r.requestTime,
            r.claimed,
            block.timestamp > r.requestTime + WITHDRAWAL_EXPIRY
        );
    }

    function getRemainingAllowance(address wallet) external view returns (uint256) {
        if (walletDeposits[wallet] >= maxDepositPerWallet) return 0;
        return maxDepositPerWallet - walletDeposits[wallet];
    }

    // ============================================
    // Owner Functions
    // ============================================

    /**
     * @notice Refill vault buffer (for withdrawal claims)
     * @dev Called by keeper when pulling funds back from Polymarket
     * @param amount Amount of USDC to refill
     * @param isReconciliation If true, reduces totalForwardedToPolymarket (funds returning from PM)
     */
    function refillBuffer(uint256 amount, bool isReconciliation) external onlyOwner {
        usdc.safeTransferFrom(msg.sender, address(this), amount);

        if (isReconciliation && amount <= totalForwardedToPolymarket) {
            totalForwardedToPolymarket -= amount;
        }

        emit BufferRefilled(amount, isReconciliation ? "reconciliation" : "owner");
    }

    function setMaxLoss(uint256 _maxLossBps) external onlyOwner {
        require(_maxLossBps <= 5000, "Max loss cannot exceed 50%");
        emit MaxLossUpdated(maxLossBps, _maxLossBps);
        maxLossBps = _maxLossBps;
    }

    function setTaxCollector(address _taxCollector) external onlyOwner {
        require(_taxCollector != address(0), "Invalid address");
        emit TaxCollectorUpdated(taxCollector, _taxCollector);
        taxCollector = _taxCollector;
    }

    function setPolymarketWallet(address _polymarketWallet) external onlyOwner {
        require(_polymarketWallet != address(0), "Invalid address");
        emit PolymarketWalletUpdated(polymarketWallet, _polymarketWallet);
        polymarketWallet = _polymarketWallet;
    }

    function setCaps(uint256 _maxPerWallet, uint256 _maxTotal) external onlyOwner {
        maxDepositPerWallet = _maxPerWallet;
        maxTotalDeposits = _maxTotal;
        emit CapsUpdated(_maxPerWallet, _maxTotal);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function setDepositsThrottled(bool _throttled) external onlyOwner {
        depositsThrottled = _throttled;
        emit DepositsThrottled(_throttled);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid address");
        usdc.safeTransfer(to, amount);
        emit EmergencyWithdraw(to, amount);
    }

    /**
     * @notice Update expected assets for reconciliation
     * @dev Use carefully - only allowed when paused for safety
     * @param _expectedAssets New expected assets value
     * @param reason Human-readable reason for the correction
     */
    function setExpectedAssets(uint256 _expectedAssets, string calldata reason) external onlyOwner whenPaused {
        uint256 oldValue = expectedAssets;
        expectedAssets = _expectedAssets;
        correctionNonce++;
        emit CorrectionExpectedAssets(correctionNonce, oldValue, _expectedAssets, reason);
    }

    /**
     * @notice Update forwarded total for reconciliation
     * @dev Use carefully - only allowed when paused for safety
     * @param _totalForwarded New total forwarded value
     * @param reason Human-readable reason for the correction
     */
    function setTotalForwarded(uint256 _totalForwarded, string calldata reason) external onlyOwner whenPaused {
        uint256 oldValue = totalForwardedToPolymarket;
        totalForwardedToPolymarket = _totalForwarded;
        correctionNonce++;
        emit CorrectionTotalForwarded(correctionNonce, oldValue, _totalForwarded, reason);
    }

    /**
     * @notice Record asset loss from trading (reduces expectedAssets to match reality)
     * @dev Only allowed when paused - call when positions lose value
     * @param lossAmount Amount of USDC lost (in 6 decimals)
     */
    function recordTradingLoss(uint256 lossAmount) external onlyOwner whenPaused {
        uint256 oldExpected = expectedAssets;
        if (lossAmount >= expectedAssets) {
            expectedAssets = 0;
        } else {
            expectedAssets -= lossAmount;
        }
        correctionNonce++;
        emit CorrectionTradingLoss(correctionNonce, lossAmount, oldExpected, expectedAssets);
    }

    /**
     * @notice Record asset gain from trading (increases expectedAssets)
     * @dev Only allowed when paused - call when positions profit
     * @param gainAmount Amount of USDC gained (in 6 decimals)
     */
    function recordTradingGain(uint256 gainAmount) external onlyOwner whenPaused {
        uint256 oldExpected = expectedAssets;
        expectedAssets += gainAmount;
        correctionNonce++;
        emit CorrectionTradingGain(correctionNonce, gainAmount, oldExpected, expectedAssets);
    }
}

